window.FISHER={"title":"Fisher, portfolio sommelier","open":"Open Fisher, the guide","close":"Close","balao":"May I suggest?","ph":"What are you after?","hello":"Meow. I am Fisher, the house sommelier. Tell me what you are in the mood for (maps, APIs, AI, water, roads) and I will pour the right project. I only serve what is on the site: no made-up vintages.","none":"I sniffed everywhere and found nothing. Try another word, or pick one of the buttons.","found":["For that palate, I suggest:","I sniffed this out:","Pairs well with:","Null hypothesis rejected. Found:"],"chips":[{"l":"Maps","q":"maps cartography"},{"l":"APIs","q":"api"},{"l":"AI","q":"ai llm rag"},{"l":"Water","q":"water hydrology basin"},{"l":"Transport","q":"transport road network"},{"l":"Predictive models","q":"predictive forecast model"},{"l":"Who is Abel?","q":"gardener personal story"}],"stop":["the","of","and","for","with","in","on","to","an","is","me","show","about","his","he","did","what","which","how","where","projects","project","abel","see","want","any","does","do","have","work"],"syn":{"ai":["artificial intelligence","llm","rag","agent","assistant","generative"],"map":["maps","cartograph","multimodal"],"maps":["map","cartograph","multimodal"],"water":["hydro","basin","catchment","streamflow","sanitation"],"road":["roads","snv","network","highway"],"roads":["road","snv","network","highway"],"transport":["logistics","snv","traffic"],"api":["apis","fastapi"],"apis":["api","fastapi"],"predictive":["forecast","prediction"],"forecast":["predictive","forecasting"],"database":["postgis","postgresql"],"satellite":["remote sensing","sentinel","fldas"],"cat":["fisher"],"books":["bookshelf","library"],"music":["playlist","band"],"certification":["certifications","oracle","ibm"],"certifications":["oracle","ibm"],"thesis":["phd"],"phd":["thesis"],"patent":["inpi"],"mining":["hydrometry","background"],"dam":["dams"],"personal":["story","gardener"],"databricks":["lakehouse"],"statistics":["statistic"]}};
